 };v<-rbindlist(out);v[,direction:=ifelse(is.na(effect),'NE',ifelse(effect>0,'Positive',ifelse(effect<0,'Negative','Zero')))];v[,label:=ifelse(is.na(effect),'NE',ifelse(q<.05,'*',''))];v[,panel:=paste0(target,' (n=',n_units,')')];v[,resource:=factor(resource,levels=c('TF RNA','CollecTRI','DoRothEA_AB','SCENIC'))]
 for(k in c('Epi','receiver')){z<-v[kind==k];plot<-ggplot(z,aes(resource,TF,fill=direction))+geom_tile(colour='white',linewidth=.4)+geom_text(aes(label=label),size=4)+facet_wrap(~panel,ncol=if(k=='Epi')3 else 2,scales='free_y')+scale_fill_manual(values=c(Negative='#67a9cf',Positive='#ef8a62',Zero='white',NE='#d9d9d9'),name='Effect direction')+labs(x='* within-model BH q < 0.05; NE = no testable regulon/RNA/model',y=NULL);export(plot,z,paste0('TF_cross_network_',k),14,if(k=='Epi')6 else 12,'Signs are compared; activity and RNA have different units. Regulon absence is NE, not counterevidence. Prespecified top CollecTRI TFs plus top SCENIC associations are shown without requiring significance.')}
